    L = []
    L.append('TODAY: ' + fmt(t) + (' (a business day)' if is_bd(t) else ' (NOT a business day)'))
    L.append('Tomorrow: ' + fmt(t + one))
    L.append('Next business day after today: ' + fmt(next_bd(t)))
    wk_end = t + datetime.timedelta(days=6 - t.weekday())
